import React, { useState, useEffect } from 'react';
// Assuming images are imported or URLs are defined in data.js
import { C, slides } from '../data';

// If the Tutor Bridge logo is a local file, import it like this:
// import tutorBridgeLogo from '../assets/tutor-bridge-logo.png'; 
// If it's a URL, define it here:
const tutorBridgeLogoURL = 'https://i.ibb.co/X7kGz7X/tutor-bridge-logo.png'; // Direct link example

export default function Hero() {
  const [current, setCurrent] = useState(0);

  useEffect(() => {
    const t = setInterval(() => setCurrent((c) => (c + 1) % slides.length), 5000);
    return () => clearInterval(t);
  }, []);

  const prev = () => setCurrent((c) => (c - 1 + slides.length) % slides.length);
  const next = () => setCurrent((c) => (c + 1) % slides.length);
  const slide = slides[current];

  return (
    <section id="hero" style={{ 
      position: 'relative', 
      minHeight: '100vh', 
      display: 'flex', 
      flexDirection: 'column', // Stack vertically for logo and main content
      overflow: 'hidden',
      backgroundColor: '#000' 
    }}>

      {/* --- Main Background Image Layer (HD & Animated) --- */}
      <div style={{
        position: 'absolute',
        inset: 0,
        backgroundImage: `url(${slide.imageUrl})`,
        backgroundSize: 'cover',
        backgroundPosition: 'center',
        transition: 'background-image 1.2s ease-in-out, transform 10s linear',
        transform: 'scale(1.1)', // Subtle initial zoom
        zIndex: 1
      }} />

      {/* --- Subtle Blue-Black Overlay for Premium Look --- */}
      <div style={{
        position: 'absolute',
        inset: 0,
        background: 'linear-gradient(135deg, rgba(0,0,10,0.85) 0%, rgba(0,0,0,0.3) 50%, rgba(0,0,20,0.7) 100%)',
        zIndex: 2
      }} />

      {/* --- Top Header with Logo --- */}
      <header style={{
        position: 'relative',
        zIndex: 10,
        width: '100%',
        maxWidth: 1280,
        margin: '0 auto',
        padding: '30px 24px 0',
        display: 'flex',
        justifyContent: 'center' // Center logo
      }}>
        <div style={{
          padding: '10px',
          background: '#fff',
          borderRadius: '50%',
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
          width: '90px',
          height: '90px',
          boxShadow: '0 10px 30px rgba(255,255,255,0.2)'
        }}>
          <img 
            src={tutorBridgeLogoURL} 
            alt="Tutor Bridge Logo" 
            style={{ width: '100%', height: 'auto' }} 
          />
        </div>
      </header>

      {/* --- Main Content Area (Two Columns) --- */}
      <div style={{ 
        flex: 1, // Take remaining vertical space
        maxWidth: 1280, 
        margin: '0 auto', 
        padding: '0 24px 60px', 
        width: '100%', 
        position: 'relative', 
        zIndex: 3,
        display: 'flex',
        alignItems: 'center', // Center content vertically within its space
        flexWrap: 'wrap', // Responsive
        gap: '40px'
      }}>

        {/* --- Left Column: Text Content --- */}
        <div style={{ flex: '1 1 500px', maxWidth: 700 }}>
          {/* Tag */}
          <div style={{ 
            display: 'inline-flex', 
            alignItems: 'center', 
            gap: 8,
            padding: '8px 16px', 
            borderRadius: 8, 
            fontSize: 12, 
            fontWeight: 700, 
            textTransform: 'uppercase', 
            letterSpacing: '0.2em', 
            marginBottom: 24, 
            background: 'rgba(255,255,255,0.1)',
            backdropFilter: 'blur(10px)',
            borderLeft: `4px solid ${C.gold}`,
            color: C.goldLight
          }}>
            <span style={{ fontSize: '14px' }}>🏆</span> {slide.tag}
          </div>

          {/* Heading */}
          <h1 style={{ 
            fontSize: 'clamp(2.5rem, 6vw, 4.2rem)', 
            fontWeight: 900, 
            color: '#fff', 
            fontFamily: "'Playfair Display', serif", 
            lineHeight: 1.1, 
            marginBottom: 24,
            textShadow: '0 10px 30px rgba(0,0,0,0.6)',
            letterSpacing: '-0.02em'
          }}>
            {slide.title}
          </h1>

          {/* Subtitle */}
          <p style={{ 
            fontSize: 'clamp(1rem, 1.8vw, 1.2rem)', 
            color: 'rgba(255,255,255,0.85)', 
            marginBottom: 48, 
            lineHeight: 1.7, 
            maxWidth: 580,
            fontWeight: 400
          }}>
            {slide.subtitle}
          </p>

          {/* Buttons */}
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 20 }}>
            <button
              onClick={() => document.getElementById('contact')?.scrollIntoView({ behavior: 'smooth' })}
              style={{ 
                padding: '18px 44px', 
                borderRadius: 12, 
                fontWeight: 800, 
                fontSize: 16, 
                background: `linear-gradient(to right, ${C.gold}, ${C.goldLight})`,
                color: '#000', 
                border: 'none', 
                cursor: 'pointer', 
                boxShadow: `0 15px 35px ${C.gold}44`,
                transition: 'all 0.3s ease' 
              }}
              onMouseEnter={e => e.currentTarget.style.transform = 'translateY(-5px)'}
              onMouseLeave={e => e.currentTarget.style.transform = 'translateY(0)'}
            >
              Get Started Free
            </button>

            <button
              style={{ 
                padding: '18px 44px', 
                borderRadius: 12, 
                fontWeight: 700, 
                fontSize: 16, 
                background: 'rgba(255,255,255,0.03)', 
                color: '#fff', 
                border: '1px solid rgba(255,255,255,0.25)', 
                cursor: 'pointer', 
                backdropFilter: 'blur(10px)',
                transition: 'all 0.3s' 
              }}
              onMouseEnter={e => e.currentTarget.style.background = 'rgba(255,255,255,0.1)'}
              onMouseLeave={e => e.currentTarget.style.background = 'rgba(255,255,255,0.03)'}
            >
              View Tutors
            </button>
          </div>
        </div>

        {/* --- Right Column: Floating Info Card --- */}
        <div style={{ flex: '1 1 300px', display: 'flex', justifyContent: 'center', zIndex: 5 }}>
          <div style={{
            width: '300px',
            padding: '30px',
            background: 'rgba(255,255,255,0.06)',
            borderRadius: '30px',
            backdropFilter: 'blur(25px)',
            border: '1px solid rgba(255,255,255,0.15)',
            boxShadow: '0 40px 80px rgba(0,0,0,0.4)',
            textAlign: 'center',
            position: 'relative',
            animation: 'float 5s ease-in-out infinite'
          }}>
            {/* Top Badges */}
            <div style={{ display: 'flex', justifyContent: 'center', gap: '10px', marginBottom: '20px' }}>
              <div style={badgeStyle}>
                <span>✅</span> Verified
              </div>
              <div style={badgeStyle}>
                <span>👨‍🎓</span> 500+ Tutors
              </div>
            </div>

            {/* Central Icon */}
            <div style={{ fontSize: '80px', color: C.gold, marginBottom: '20px' }}>
              🎓 {/* Use a high-quality graduation icon here if possible */}
            </div>

            {/* Description */}
            <p style={{ color: 'rgba(255,255,255,0.9)', fontSize: '14px', lineHeight: 1.5 }}>
              Expert tutors ready to unlock your academic potential with personalized learning.
            </p>
          </div>
        </div>
      </div>

      {/* --- Slider Navigation (Bottom Center) --- */}
      <div style={{ 
        position: 'relative',
        zIndex: 10,
        width: '100%',
        maxWidth: 1280,
        margin: '0 auto',
        padding: '0 24px 40px',
        display: 'flex', 
        alignItems: 'center', 
        justifyContent: 'center',
        gap: 24 
      }}>
        <div style={{ display: 'flex', gap: 10 }}>
          {slides.map((_, i) => (
            <div 
              key={i} 
              onClick={() => setCurrent(i)}
              style={{ 
                width: i === current ? 45 : 12, 
                height: 5, 
                borderRadius: 2.5, 
                background: i === current ? C.gold : 'rgba(255,255,255,0.25)', 
                cursor: 'pointer',
                transition: 'all 0.4s' 
              }} 
            />
          ))}
        </div>
        <div style={{ display: 'flex', gap: 15 }}>
          <button onClick={prev} style={navButtonStyle}>←</button>
          <button onClick={next} style={navButtonStyle}>→</button>
        </div>
      </div>

      {/* Floating Animation Definition */}
      <style>{`
        @keyframes float {
          0%, 100% { transform: translateY(0px) rotate(0deg); }
          50% { transform: translateY(-20px) rotate(1deg); }
        }
      `}</style>
    </section>
  );
}

// Styling Helper consts
const navButtonStyle = {
  width: 55,
  height: 55,
  borderRadius: '50%',
  border: '1px solid rgba(255,255,255,0.2)',
  background: 'rgba(255,255,255,0.06)',
  color: '#fff',
  fontSize: '22px',
  cursor: 'pointer',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  backdropFilter: 'blur(5px)',
  transition: '0.3s ease-in-out',
  ":hover": {
    background: 'rgba(255,255,255,0.15)'
  }
};

const badgeStyle = {
  display: 'flex',
  alignItems: 'center',
  gap: '6px',
  padding: '6px 14px',
  background: 'rgba(255,255,255,0.08)',
